import {MODULAR_VERSION} from './modular-brain-layout.js';
import {WORLD_SAVE_VERSION} from './world-save.js';
import {EXPERIMENT_PROTOCOL} from './experiment-plan.js';
import {PHYSIOLOGY_GUIDE_TEXT} from './guide-physiology-text.js';
import {CARE_GUIDE_TEXT as old} from './guide-child-care-text.js';
import {p,a,v,table,details} from './guide-markup.js';
import {MODULAR_GRAPH_SPECS} from './modular-brain-layout.js';
const param=key=>`<span class="guide-value" data-guide-param="${key}"></span>`;
const roles={cells:'Обрабатывает каждую видимую клетку; её признаки усредняются для ситуации.',context:'Объединяет тело, память, сводку клеток и процесс.',target:'Преобразует признаки рассматриваемой цели действия.',operation:'Задаёт компоненты оценки выбранного типа операции.',direct:'Даёт отдельный вклад в оценку варианта.',attention:'Запрашивает повторный основной выбор во время действия или покоя.'};
const structure=p('У всех частей нового мозга могут эволюционировать скрытые нейроны, слои и связи. Каждый блок сохраняет назначение и размеры внешних входов и выходов; его внутренние пути меняются при рождении. Основной мозг за жизнь обучает веса, малый мозг наследует и мутирует их без личного обучения.')
 +table('Задачи блоков',['Блок','Что делает','Выходов'],MODULAR_GRAPH_SPECS.map(s=>[s.label,roles[s.key],v(s.outputs)]))
 +p('Например, два скрытых слоя кодировщика позволяют последовательно преобразовать признаки клетки. Проекция цели при этом может оставаться без скрытых слоёв. Добавленные нейроны не имеют заранее назначенного смысла: полезность их вычислений определяется последствиями решений.')
 +details('Слои, связи и вычисления',p('Связи направлены вперёд, могут пропускать слои и соединять вход непосредственно с выходом. Пустые слои пропускаются; скрытых нейронов может не быть. Скрытые нейроны используют tanh. У кодировщика tanh ограничивает также выход, у остальных блоков выход линейный.')
 +p('Цена определяется действующими вычислениями, включая обучение и проверки малого мозга. Лишённый пути к выходу скрытый узел не вычисляется. Дополнительный слой с редкими связями может потребовать меньше операций, чем плотная сеть без скрытых узлов. Когда проекция цели и прямая оценка линейны, сохраняется быстрый расчёт общей головки операции.'));
export const MODULAR_GUIDE_TEXT={
 'guide-brain-cost-body':PHYSIOLOGY_GUIDE_TEXT['guide-brain-cost-body']+p('У новой схемы в стоимость включены действующие узлы и связи всех блоков. Проекция операции переиспользуется в пределах одного решения. Если цель и прямая оценка не имеют скрытых нейронов, применяется быстрая линейная свёртка; иначе считается общий проход соответствующих DAG. Фиксированный эталон цены сохранён, а отношение вычислений меняется со структурой.'),
 'guide-brain-structure-body':structure+p(`Назначение входов сохранено: см. ${a('observation','наблюдения')} и ${a('brain-cost','энергетическую цену мозга')}. Схема выбранного жителя показывает его фактические слои и связи.`),
 'guide-structure-evolution-body':p('Вес и наличие связи — разные наследуемые свойства. Числовая мутация сдвигает существующие веса и смещения; структурная добавляет или удаляет пути и нейроны. У каждого блока свои профили обоих видов изменений.')
 +p(`Исходный числовой профиль: форма A — ${param('initialMutation.cells.shape')}, потолок r — ${param('initialMutation.cells.ceiling')}. Для структуры кодировщика начальная вероятность — ${param('initialMutation.cellsStructure.rate')}, сила — ${param('initialMutation.cellsStructure.strength')}. Эти стартовые значения пользователь может менять.`)
 +details('Как работает мутация',p('Каждый существующий числовой параметр включённой группы меняется при рождении. A задаёт распределение размера сдвига: больше A — крупные изменения встречаются чаще. r ограничивает относительный сдвиг. Опорный масштаб и минимальный шаг позволяют менять нулевые веса.')
 +p('У структурной группы отдельный шанс события. Сила задаёт бюджет изменений относительно нынешнего числа нейронов и связей, с вероятностным округлением. Новый нейрон получает входящую и исходящую связи; исходящий вес начинается с нуля и затем может обучаться или мутировать. Удаление нейрона удаляет его связи. Обратных связей и циклов нет.')
 +p('Выключение группы сохраняет её параметры и регуляторы при рождении. Структура и веса отключаются отдельно. Общее выключение мутаций запрещает оба вида; личное обучение задаётся своим переключателем. Регуляторы изменяются по родительскому профилю поведенческой группы.'))
 +p(`Память и выученные поправки не входят в наследство. См. ${a('genome','состав генома')} и ${a('learning','личное обучение')}.`),
 'guide-genome-body':p(`Геном ${v(MODULAR_VERSION)} описывает врождённую основу жителя. Он содержит шесть сетей, свойства поведения и тела, а также регуляторы изменений при рождении. Личные воспоминания и обученные поправки хранятся отдельно.`)
 +table('Что наследуется',['Часть','Содержание'],[['Сети','Слои, существующие связи, веса и смещения каждого блока'],['Поведение и тело','Чувствительности, обучение, память, развитие, пищеварение и ношение ребёнка'],['Мутации','Свои A/r числовой группы и вероятность/сила структурной группы каждого блока']])
 +p('Например, изменение веса кодировщика не требует появления нового нейрона. Добавление слоя меняет устройство сети, после чего новые веса могут обучаться за жизнь. Выключение соответствующей группы позволяет проверить эти процессы отдельно.')
 +details('Формат и совместимость',p('Размер генома зависит от числа существующих нейронов и связей. В конце хранятся размеры блоков и признак схемы; загрузчик проверяет границы, направления, отсутствие циклов и допустимость чисел. Старые геномы читаются для анализа по собственной раскладке; их числа автоматически не превращаются в новую схему.')),
 'wiki-saves':p('Выбирайте файл по тому, что хотите сохранить: полный мир продолжает жизнь с личным опытом; геном задаёт только наследуемую основу; план задаёт условия повторов; отчёт содержит результаты.')
 +table('Форматы текущего выпуска',['Файл','Схема','Назначение'],[['Геном',v(MODULAR_VERSION),'Устройство шести блоков и наследуемые свойства'],['Полный мир',v(WORLD_SAVE_VERSION),'Тела, процессы, пища, мозги, личный опыт и RNG'],['План',EXPERIMENT_PROTOCOL,'Начальные настройки, сочетания параметров и повторы']])
 +p('Полный мир сохраняет связь ношения родителя и ребёнка, её срок и пищу. Врождённые веса восстанавливаются из генома; личные поправки, следы обучения и память сохраняются отдельно. Загрузка не выполняет шаг симуляции.')
 +details('Прежние файлы',p('Результаты прежних опытов и геномы остаются доступны для анализа. Полные миры иной схемы продолжайте в соответствующем выпуске. Ошибка загрузки не заменяет уже открытый мир.')),
 'guide-actions-body':old['guide-actions-body']+p(`Само действие зачатия имеет отдельные время ${param('physiology.conceiveSteps')} и двигательную ставку ${param('physiology.conceiveRate')}. После его успешного завершения начинается беременность с собственным сроком и платежами. Время и цена большинства действий собраны в группе «Действия: время, расход энергии и объём».`),
};
